/** Wall-clock interpolated position in microseconds. */
export function currentPosition(p: Player): number | null {
  const pos = p.position_us;
  const ts = p.position_sampled_at_us;
  if (pos == null || ts == null) return null;
  const posNum = Number(pos);
  if (p.playback_status !== "playing") return posNum;
  const nowUs = Date.now() * 1000;
  const length =
    p.metadata.length_us == null
      ? Number.MAX_SAFE_INTEGER
      : Number(p.metadata.length_us);
  return Math.min(posNum + (nowUs - Number(ts)), length);
}
